typedef unsigned int u_int;

template <class T>
class singleton_ptr
{
  T *p;
public:
  operator T *() const { return p; }
};

class singleton
{
protected:
  singleton() {}
  virtual ~singleton() {}
};

class os_developer_options : public singleton
{
public:
  enum flags_t { FLAG_MEM_FREE_SCREEN = 92 };
  bool is_flagged(flags_t flag) const { return flags[flag]; }
  static os_developer_options *inst() { return instance; }
private:
  static singleton_ptr<os_developer_options> instance;
  bool flags[93];
};

struct debug_info_t
{
  bool dump_frame_info : 1;
  bool dump_threads : 1;
  bool render_spheres : 1;
  bool turtle_watch : 1;
  bool halt_on_asserts : 1;
  bool stay_halted : 1;
  bool simulate32meg : 1;
  bool assert_screen : 1;
  bool mem_free_screen : 1;
};

extern debug_info_t g_debug;

struct nglQuadVertex
{
  float X, Y;
  float U, V;
  u_int Color;
};

struct nglTexture;
struct nglQuad
{
  nglQuadVertex Verts[4];
  float Z;
  u_int MapFlags;
  u_int BlendMode;
  u_int BlendModeConstant;
  nglTexture *Tex;
};

struct nglFont;
extern nglFont *nglSysFont;

void nglInitQuad(nglQuad *Quad);
void nglListBeginScene();
int nglGetScreenWidth();
int nglGetScreenHeight();
void nglSetQuadRect(nglQuad *Quad, float x1, float y1, float x2, float y2);
void nglSetQuadColor(nglQuad *Quad, u_int c);
void nglSetQuadZ(nglQuad *Quad, float z);
void nglListAddQuad(nglQuad *Quad);
void nglListAddString(nglFont *Font, float x, float y, double z, u_int Color, const char *Text, ...);
int mem_get_total_avail(int heapid = 0);
void nglListEndScene();

class game
{
public:
  void render_mem_free_screen();
};

void game::render_mem_free_screen()
{
	if ( os_developer_options::inst()->is_flagged(os_developer_options::FLAG_MEM_FREE_SCREEN) || g_debug.mem_free_screen )
	{
		nglQuad q;

		nglInitQuad(&q);
		nglListBeginScene();
		nglSetQuadRect (&q, nglGetScreenWidth() - 100, nglGetScreenHeight() - 31, nglGetScreenWidth(), nglGetScreenHeight());
		nglSetQuadColor (&q, ((int)((0)+1)>>1) | ( ((int)((0)+1)>>1) << 8 ) | ( ((int)((0)+1)>>1) << 16 ) | ( ((int)((128)+1)>>1) << 24 ));
		nglSetQuadZ (&q, 0.3f);
		nglListAddQuad (&q);

		nglListAddString (nglSysFont, nglGetScreenWidth() - 95, nglGetScreenHeight() - 29, 0.2f,
			0x80808080, "RAM Free:");
		nglListAddString (nglSysFont, nglGetScreenWidth() - 95, nglGetScreenHeight() - 15, 0.2f,
			0x80808080, "%d", mem_get_total_avail() );

		nglListEndScene();
	}
}
